<?php
namespace App\Application\Trust;use App\Application\Audit\AuditWriter;use App\Application\Events\OutboxWriter;use App\Models\{FraudRuleVersion,RiskAlert,User};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class FraudReviewService{public function __construct(private AuditWriter$a,private OutboxWriter$o){}private function hash(array$d):string{ksort($d);return hash('sha256',json_encode($d,JSON_THROW_ON_ERROR));}public function createRule(array$d,User$u):FraudRuleVersion{$h=$this->hash($d['conditions']);return FraudRuleVersion::create([...$d,'status'=>'DRAFT','rule_hash'=>$h,'created_by'=>$u->id]);}public function approveRule(FraudRuleVersion$r,User$u):FraudRuleVersion{return DB::transaction(function()use($r,$u){$r=FraudRuleVersion::whereKey($r->id)->lockForUpdate()->firstOrFail();if($r->status!=='DRAFT'||$r->created_by===$u->id)throw ValidationException::withMessages(['status'=>__('wave9.maker_checker')]);$overlap=FraudRuleVersion::where('code',$r->code)->where('status','ACTIVE')->where('effective_from','<=',$r->effective_until??'9999-12-31')->where(fn($q)=>$q->whereNull('effective_until')->orWhere('effective_until','>=',$r->effective_from))->exists();if($overlap)throw ValidationException::withMessages(['effective_from'=>__('wave9.rule_overlap')]);$r->update(['status'=>'ACTIVE','approved_by'=>$u->id,'approved_at'=>now()]);$this->a->record('fraud.rule.approved','fraud_rule_version',$r->id,['hash'=>$r->rule_hash]);return$r->refresh();});}public function alert(string$tenant,array$d,User$u):RiskAlert{$hash=$this->hash($d);if($x=RiskAlert::where(['tenant_id'=>$tenant,'idempotency_key'=>$d['idempotency_key']])->first()){if(!hash_equals($x->payload_hash,$hash))throw ValidationException::withMessages(['idempotency_key'=>__('wave9.idempotency_conflict')]);return$x;}return DB::transaction(function()use($tenant,$d,$u,$hash){$rule=FraudRuleVersion::whereKey($d['fraud_rule_version_id'])->where('status','ACTIVE')->where('effective_from','<=',today())->where(fn($q)=>$q->whereNull('effective_until')->orWhere('effective_until','>=',today()))->firstOrFail();$x=RiskAlert::create([...$d,'tenant_id'=>$tenant,'risk_score'=>$rule->risk_points,'status'=>'OPEN','payload_hash'=>$hash]);$this->a->record('fraud.alert.opened','risk_alert',$x->id,['score'=>$x->risk_score]);$this->o->record('fraud.alert.opened','risk_alert',$x->id,['risk_alert_id'=>$x->id]);return$x;});}/** REQ-DUP-009 legacy risk-alerts contract: caller-supplied score, no rule version; severity banding kept from the legacy controller. */public function manualAlert(string$tenant,array$d,User$u):RiskAlert{$severity=match(true){$d['risk_score']>=80=>'CRITICAL',$d['risk_score']>=60=>'HIGH',$d['risk_score']>=30=>'MEDIUM',default=>'LOW'};$x=RiskAlert::create([...$d,'tenant_id'=>$tenant,'severity'=>$severity,'status'=>'OPEN']);$this->a->record('risk.alert.created','risk_alert',$x->id,['severity'=>$severity,'score'=>$d['risk_score']]);return$x;}
/** Both vocabularies (legacy CLEARED/CONFIRMED_FRAUD/MONITOR/ESCALATE_COMPLIANCE, trust CLEARED/CONFIRMED/ESCALATED); escalations end ESCALATED, everything else DECIDED. */public function decide(RiskAlert$x,string$decision,string$notes,User$u):RiskAlert{if(!in_array($x->status,['OPEN','UNDER_REVIEW'],true)||$x->assigned_to===$u->id)throw ValidationException::withMessages(['status'=>__('wave9.review_invalid')]);$x->update(['status'=>in_array($decision,['ESCALATED','ESCALATE_COMPLIANCE'],true)?'ESCALATED':'DECIDED','decision'=>$decision,'decision_notes'=>$notes,'decided_by'=>$u->id,'decided_at'=>now(),'version'=>$x->version+1]);$this->a->record('fraud.alert.decided','risk_alert',$x->id,['decision'=>$decision]);return$x->refresh();}}
